import { describe, expect, it } from 'vitest';

// The bundle graph this guard protects is wider than apps/staged/src: the
// workspace packages staged depends on export raw sources, so their .ts and
// .svelte files compile into the same Vite bundle.
const appSourceFiles = import.meta.glob('/src/**/*.{ts,svelte}', {
  query: '?raw',
  import: 'default',
  eager: true,
}) as Record<string, string>;

const packageSourceFiles = import.meta.glob('../../../../../../packages/*/src/**/*.{ts,svelte}', {
  query: '?raw',
  import: 'default',
  eager: true,
}) as Record<string, string>;

/** App keys are vite-root absolute (`/src/...`); package keys are relative to this file. */
function toRepoRelativePath(path: string): string {
  if (path.startsWith('/')) {
    return `apps/staged${path}`;
  }
  return path.replace(/^(?:\.\.\/)+/, '');
}

const bundledSourceFiles = new Map(
  [...Object.entries(appSourceFiles), ...Object.entries(packageSourceFiles)].map(
    ([path, source]) => [toRepoRelativePath(path), source]
  )
);

const allowedFullMapFiles = new Set([
  'apps/staged/src/lib/features/actions/lucideIcons.ts',
  'apps/staged/src/lib/features/actions/lucideIcons.guard.test.ts',
]);

const bannedLucideEntrypointPattern =
  /(["'`])@lucide\/svelte(?:\/icons(?:\/index(?:\.[a-z]+)?)?)?(?:\?[^"'`]*)?\1/;

function findBannedLucideEntrypointImports(): string[] {
  return [...bundledSourceFiles]
    .filter(
      ([path, source]) =>
        !allowedFullMapFiles.has(path) && bannedLucideEntrypointPattern.test(source)
    )
    .map(([path]) => path)
    .sort();
}

describe('Lucide icon imports', () => {
  it('scans both the app sources and the workspace package sources', () => {
    // A silently empty glob (a directory rename, a wrong `../` count) would
    // hollow out this guard without failing it, so assert coverage directly.
    expect(bundledSourceFiles.has('apps/staged/src/lib/features/actions/lucideIcons.ts')).toBe(
      true
    );
    expect(
      bundledSourceFiles.has('packages/diff-viewer/src/lib/components/DiffViewer.svelte')
    ).toBe(true);
  });

  it('keeps barrel and full-map imports out of the bundled source graph', () => {
    const violations = findBannedLucideEntrypointImports();

    expect(
      violations,
      [
        'Do not import Lucide through the barrel or full icon map anywhere in',
        "staged's bundle graph (apps/staged/src plus the workspace packages it",
        'pulls in). Use per-icon @lucide/svelte/icons/<name> imports; the full',
        'map is only reachable via loadIconMap() in lucideIcons.ts. Breaking this',
        'invariant adds ~620 kB to the main bundle.',
        `Offending files: ${violations.join(', ')}`,
      ].join(' ')
    ).toEqual([]);
  });

  it('matches the banned entrypoints without blocking per-icon imports', () => {
    expect(bannedLucideEntrypointPattern.test("import { Play } from '@lucide/svelte';")).toBe(true);
    expect(bannedLucideEntrypointPattern.test("import('@lucide/svelte')")).toBe(true);
    expect(
      bannedLucideEntrypointPattern.test("import * as icons from '@lucide/svelte/icons';")
    ).toBe(true);
    expect(bannedLucideEntrypointPattern.test("import('@lucide/svelte/icons/index')")).toBe(true);
    expect(bannedLucideEntrypointPattern.test("import('@lucide/svelte/icons/index.js')")).toBe(
      true
    );
    expect(
      bannedLucideEntrypointPattern.test("import Play from '@lucide/svelte/icons/play';")
    ).toBe(false);
  });
});

//! Data models for action execution and detection

use serde::{Deserialize, Serialize};

/// The type of a project action
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum ActionType {
    Build,
    Test,
    Format,
    Check,
    Prerun,
    Run,
    CleanUp,
}

impl ActionType {
    pub fn as_str(&self) -> &'static str {
        match self {
            ActionType::Build => "build",
            ActionType::Test => "test",
            ActionType::Format => "format",
            ActionType::Check => "check",
            ActionType::Prerun => "prerun",
            ActionType::Run => "run",
            ActionType::CleanUp => "cleanUp",
        }
    }

    pub fn parse(s: &str) -> Option<Self> {
        match s {
            "build" => Some(ActionType::Build),
            "test" => Some(ActionType::Test),
            "format" => Some(ActionType::Format),
            "check" => Some(ActionType::Check),
            "prerun" => Some(ActionType::Prerun),
            "run" => Some(ActionType::Run),
            "cleanUp" => Some(ActionType::CleanUp),
            _ => None,
        }
    }
}

/// Status of an action execution
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ActionStatus {
    Running,
    Completed,
    Failed,
    Stopped,
}

/// Represents a single output chunk with its metadata
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct OutputChunk {
    pub chunk: String,
    pub stream: String, // "stdout" or "stderr"
    pub timestamp: i64,
}

/// How a "run" action detects whether the process is running and/or its endpoint.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "camelCase")]
pub enum RunDetectionMode {
    Autodetect,
    EndpointRegex { pattern: String },
    RunningRegex { pattern: String },
    NoDetection,
}

/// Events emitted during action execution
#[derive(Debug, Clone)]
pub enum ExecutionEvent {
    /// Action has started
    Started {
        execution_id: String,
        started_at: i64,
    },
    /// Output chunk received
    Output {
        execution_id: String,
        chunk: String,
        stream: String, // "stdout" or "stderr"
        timestamp: i64,
    },
    /// Action status changed
    StatusChanged {
        execution_id: String,
        status: ActionStatus,
        exit_code: Option<i32>,
        started_at: Option<i64>,
        completed_at: Option<i64>,
    },
}

/**
 * The one module allowed to reach for Lucide's complete icon set, plus the
 * per-action-type icon every surface falls back to.
 *
 * A pinned action can carry any Lucide icon name, so the picker has to be able
 * to render all ~1,750 of them — but pulling that map into the main graph would
 * drag every icon into the app bundle. `loadIconMap()` is a single cached
 * dynamic import, which Vite code-splits into one lazily fetched ~600 kB chunk:
 * nothing loads until a card renders a custom icon or the picker opens.
 * **Never statically import that map** — everything else in the app keeps using
 * per-icon `@lucide/svelte/icons/x` imports.
 *
 * It has to be `@lucide/svelte/icons/index` rather than the `@lucide/svelte`
 * barrel: the barrel is *statically* imported elsewhere (the diff-viewer
 * package), so a dynamic import of it can't move into its own chunk and the
 * whole icon set lands in the main bundle instead — measurably, +620 kB.
 *
 * Stored icon names are kebab-case, matching the names on lucide.dev; the map
 * is keyed by PascalCase export names, which [`./iconNames`] bridges.
 */

import Play from '@lucide/svelte/icons/play';
import Hammer from '@lucide/svelte/icons/hammer';
import FlaskConical from '@lucide/svelte/icons/flask-conical';
import CheckCircle from '@lucide/svelte/icons/check-circle';
import Wrench from '@lucide/svelte/icons/wrench';
import Zap from '@lucide/svelte/icons/zap';
import Wand2 from '@lucide/svelte/icons/wand-2';
import Trash2 from '@lucide/svelte/icons/trash-2';
import { pascalToKebab } from './iconNames';

export type IconComponent = typeof Play;

/**
 * The icon an action shows when it has picked none of its own — also the
 * fallback when a stored name is no longer a Lucide icon. Shared by the card
 * header, the Actions submenu and the settings list, so an action type looks
 * the same everywhere.
 */
export function getActionTypeIcon(actionType: string): IconComponent {
  switch (actionType) {
    case 'prerun':
      return Zap;
    case 'run':
      return Play;
    case 'build':
      return Hammer;
    case 'format':
      return Wand2;
    case 'check':
      return CheckCircle;
    case 'test':
      return FlaskConical;
    case 'cleanUp':
      return Trash2;
    default:
      return Wrench;
  }
}

type LucideIconMap = Record<string, IconComponent>;

let iconMapPromise: Promise<LucideIconMap> | null = null;

/**
 * Every Lucide icon keyed by kebab-case name, fetched once and shared by every
 * caller afterwards.
 */
export function loadIconMap(): Promise<LucideIconMap> {
  iconMapPromise ??= import('@lucide/svelte/icons/index').then((module) => {
    const byKebab: LucideIconMap = {};
    for (const [pascal, component] of Object.entries(module)) {
      byKebab[pascalToKebab(pascal)] = component as IconComponent;
    }
    return byKebab;
  });
  return iconMapPromise;
}

/** One icon by kebab-case name, or null when Lucide has no such icon. */
export async function loadIconComponent(name: string): Promise<IconComponent | null> {
  return (await loadIconMap())[name] ?? null;
}

package server

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/loganj/penpal/internal/config"
)

// E-PENPAL-INSTALL-CLI: verifies GET /api/install-tools returns status JSON.
func TestInstallToolsStatus_ReturnsJSON(t *testing.T) {
	s, _, _ := testServer(t)
	s.installCfg = &installConfig{binDir: t.TempDir()}

	req := httptest.NewRequest(http.MethodGet, "/api/install-tools", nil)
	rec := httptest.NewRecorder()
	s.ServeHTTP(rec, req)

	if rec.Code != http.StatusOK {
		t.Fatalf("expected 200, got %d: %s", rec.Code, rec.Body.String())
	}

	var resp installToolsResponse
	if err := json.Unmarshal(rec.Body.Bytes(), &resp); err != nil {
		t.Fatalf("parse JSON: %v", err)
	}

	// CLI should not be installed (empty temp binDir has no symlink)
	if resp.CLI.Installed {
		t.Error("expected CLI not installed")
	}
	// Plugin status depends on host machine — just verify the field exists
}

// E-PENPAL-INSTALL-CLI: verifies existing CLI symlink is detected.
func TestInstallToolsStatus_DetectsExistingSymlink(t *testing.T) {
	s, _, _ := testServer(t)
	binDir := t.TempDir()
	s.installCfg = &installConfig{binDir: binDir}

	// Create a symlink manually
	symlinkPath := filepath.Join(binDir, "penpal")
	target := "/Applications/Penpal.app/Contents/MacOS/penpal-cli"
	if err := os.Symlink(target, symlinkPath); err != nil {
		t.Fatal(err)
	}

	req := httptest.NewRequest(http.MethodGet, "/api/install-tools", nil)
	rec := httptest.NewRecorder()
	s.ServeHTTP(rec, req)

	var resp installToolsResponse
	json.Unmarshal(rec.Body.Bytes(), &resp)

	if !resp.CLI.Installed {
		t.Error("expected CLI installed")
	}
	if resp.CLI.Path != target {
		t.Errorf("expected path %q, got %q", target, resp.CLI.Path)
	}
}

// E-PENPAL-INSTALL-CLI: verifies POST /api/install-tools creates CLI symlink.
func TestInstallToolsInstall_CreatesSymlink(t *testing.T) {
	s, _, _ := testServer(t)
	binDir := t.TempDir()
	appRoot := t.TempDir()

	// Create the fake app bundle structure
	macosDir := filepath.Join(appRoot, "Contents", "MacOS")
	marketplaceDir := filepath.Join(appRoot, "Contents", "Resources", ".claude-plugin")
	os.MkdirAll(macosDir, 0o755)
	os.MkdirAll(marketplaceDir, 0o755)
	os.WriteFile(filepath.Join(marketplaceDir, "marketplace.json"), []byte(`{"name":"penpal","plugins":[]}`), 0o644)
	os.WriteFile(filepath.Join(macosDir, "penpal-cli"), []byte("fake"), 0o755)

	s.installCfg = &installConfig{binDir: binDir, appRoot: appRoot}

	req := httptest.NewRequest(http.MethodPost, "/api/install-tools", nil)
	rec := httptest.NewRecorder()
	s.ServeHTTP(rec, req)

	if rec.Code != http.StatusOK {
		t.Fatalf("expected 200, got %d: %s", rec.Code, rec.Body.String())
	}

	var resp installToolsResponse
	json.Unmarshal(rec.Body.Bytes(), &resp)

	if !resp.CLI.Installed {
		t.Errorf("expected CLI installed, got error: %s", resp.CLI.Error)
	}

	// Verify symlink exists
	symlinkPath := filepath.Join(binDir, "penpal")
	target, err := os.Readlink(symlinkPath)
	if err != nil {
		t.Fatalf("symlink not created: %v", err)
	}
	expectedTarget := filepath.Join(appRoot, "Contents", "MacOS", "penpal-cli")
	if target != expectedTarget {
		t.Errorf("symlink points to %q, expected %q", target, expectedTarget)
	}
}

// E-PENPAL-INSTALL-CLI: verifies install is idempotent (second call succeeds).
func TestInstallToolsInstall_Idempotent(t *testing.T) {
	s, _, _ := testServer(t)
	binDir := t.TempDir()
	appRoot := t.TempDir()

	macosDir := filepath.Join(appRoot, "Contents", "MacOS")
	marketplaceDir := filepath.Join(appRoot, "Contents", "Resources", ".claude-plugin")
	os.MkdirAll(macosDir, 0o755)
	os.MkdirAll(marketplaceDir, 0o755)
	os.WriteFile(filepath.Join(marketplaceDir, "marketplace.json"), []byte(`{"name":"penpal","plugins":[]}`), 0o644)
	os.WriteFile(filepath.Join(macosDir, "penpal-cli"), []byte("fake"), 0o755)

	s.installCfg = &installConfig{binDir: binDir, appRoot: appRoot}

	// Call POST twice — second call should not error
	for i := 0; i < 2; i++ {
		req := httptest.NewRequest(http.MethodPost, "/api/install-tools", nil)
		rec := httptest.NewRecorder()
		s.ServeHTTP(rec, req)

		if rec.Code != http.StatusOK {
			t.Fatalf("call %d: expected 200, got %d: %s", i+1, rec.Code, rec.Body.String())
		}

		var resp installToolsResponse
		json.Unmarshal(rec.Body.Bytes(), &resp)

		if !resp.CLI.Installed {
			t.Errorf("call %d: expected CLI installed, got error: %s", i+1, resp.CLI.Error)
		}
	}
}

func TestInstallToolsInstall_MethodNotAllowed(t *testing.T) {
	s, _, _ := testServer(t)

	req := httptest.NewRequest(http.MethodDelete, "/api/install-tools", nil)
	rec := httptest.NewRecorder()
	s.ServeHTTP(rec, req)

	if rec.Code != http.StatusMethodNotAllowed {
		t.Fatalf("expected 405, got %d", rec.Code)
	}
}

// E-PENPAL-CLAUDE-PATH: verifies install status includes claudeBin field.
func TestInstallToolsStatus_IncludesClaudeBin(t *testing.T) {
	s, _, _ := testServer(t)
	// Create a fake claude binary and inject it via installCfg
	dir := t.TempDir()
	fakeClaude := filepath.Join(dir, "claude")
	os.WriteFile(fakeClaude, []byte("#!/bin/sh\n"), 0755)

	s.installCfg = &installConfig{binDir: t.TempDir(), claudeBin: fakeClaude}

	req := httptest.NewRequest(http.MethodGet, "/api/install-tools", nil)
	rec := httptest.NewRecorder()
	s.ServeHTTP(rec, req)

	var resp installToolsResponse
	json.Unmarshal(rec.Body.Bytes(), &resp)

	if resp.ClaudeBin != fakeClaude {
		t.Errorf("expected claudeBin %q, got %q", fakeClaude, resp.ClaudeBin)
	}
}

func TestInstallToolsStatus_ClaudeBinEmpty(t *testing.T) {
	s, _, _ := testServer(t)
	s.installCfg = &installConfig{binDir: t.TempDir(), claudeBin: ""}

	req := httptest.NewRequest(http.MethodGet, "/api/install-tools", nil)
	rec := httptest.NewRecorder()
	s.ServeHTTP(rec, req)

	var resp installToolsResponse
	json.Unmarshal(rec.Body.Bytes(), &resp)

	if resp.ClaudeBin != "" {
		t.Errorf("expected empty claudeBin, got %q", resp.ClaudeBin)
	}
}

// E-PENPAL-INSTALL-PLUGIN: verifies plugin install fails when claude binary is missing.
func TestPerformInstall_NoClaudeBin_ReportsError(t *testing.T) {
	appRoot := t.TempDir()
	macosDir := filepath.Join(appRoot, "Contents", "MacOS")
	marketplaceDir := filepath.Join(appRoot, "Contents", "Resources", ".claude-plugin")
	os.MkdirAll(macosDir, 0o755)
	os.MkdirAll(marketplaceDir, 0o755)
	os.WriteFile(filepath.Join(marketplaceDir, "marketplace.json"), []byte(`{}`), 0o644)
	os.WriteFile(filepath.Join(macosDir, "penpal-cli"), []byte("fake"), 0o755)

	cfg := installConfig{binDir: t.TempDir(), appRoot: appRoot, claudeBin: ""}
	resp := performInstall(cfg)

	if resp.Plugin.Installed {
		t.Error("expected plugin not installed when claudeBin is empty")
	}
	if !strings.Contains(resp.Plugin.Error, "claude binary not found") {
		t.Errorf("expected 'claude binary not found' error, got %q", resp.Plugin.Error)
	}
}

// E-PENPAL-CLAUDE-PATH: verifies PUT /api/claude-path saves and persists valid path.
func TestClaudePath_PUT_Valid(t *testing.T) {
	s, _, _ := testServer(t)
	cfgPath := filepath.Join(t.TempDir(), "config.json")
	s.cfgPath = cfgPath

	// Create a fake claude binary
	dir := t.TempDir()
	fakeClaude := filepath.Join(dir, "claude")
	os.WriteFile(fakeClaude, []byte("#!/bin/sh\n"), 0755)

	body := `{"path":"` + fakeClaude + `"}`
	req := httptest.NewRequest(http.MethodPut, "/api/claude-path", strings.NewReader(body))
	rec := httptest.NewRecorder()
	s.ServeHTTP(rec, req)

	if rec.Code != http.StatusOK {
		t.Fatalf("expected 200, got %d: %s", rec.Code, rec.Body.String())
	}

	var resp map[string]string
	json.Unmarshal(rec.Body.Bytes(), &resp)
	if resp["path"] != fakeClaude {
		t.Errorf("expected path %q, got %q", fakeClaude, resp["path"])
	}

	// Verify it was persisted
	saved, err := config.Load(cfgPath)
	if err != nil {
		t.Fatalf("load config: %v", err)
	}
	if saved.ClaudePath != fakeClaude {
		t.Errorf("expected persisted claudePath %q, got %q", fakeClaude, saved.ClaudePath)
	}
}

// E-PENPAL-CLAUDE-PATH: verifies PUT /api/claude-path rejects invalid path.
func TestClaudePath_PUT_InvalidPath(t *testing.T) {
	s, _, _ := testServer(t)

	body := `{"path":"/nonexistent/path/to/claude"}`
	req := httptest.NewRequest(http.MethodPut, "/api/claude-path", strings.NewReader(body))
	rec := httptest.NewRecorder()
	s.ServeHTTP(rec, req)

	if rec.Code != http.StatusBadRequest {
		t.Fatalf("expected 400, got %d: %s", rec.Code, rec.Body.String())
	}
}

// E-PENPAL-CLAUDE-PATH: verifies PUT /api/claude-path rejects empty path.
func TestClaudePath_PUT_EmptyPath(t *testing.T) {
	s, _, _ := testServer(t)

	body := `{"path":""}`
	req := httptest.NewRequest(http.MethodPut, "/api/claude-path", strings.NewReader(body))
	rec := httptest.NewRecorder()
	s.ServeHTTP(rec, req)

	if rec.Code != http.StatusBadRequest {
		t.Fatalf("expected 400, got %d: %s", rec.Code, rec.Body.String())
	}
}

// E-PENPAL-CLAUDE-PATH: verifies GET /api/claude-path returns remembered path.
func TestClaudePath_GET(t *testing.T) {
	s, _, _ := testServer(t)
	// Pre-set a remembered path
	dir := t.TempDir()
	fakeClaude := filepath.Join(dir, "claude")
	os.WriteFile(fakeClaude, []byte("#!/bin/sh\n"), 0755)
	s.cfg.ClaudePath = fakeClaude

	req := httptest.NewRequest(http.MethodGet, "/api/claude-path", nil)
	rec := httptest.NewRecorder()
	s.ServeHTTP(rec, req)

	if rec.Code != http.StatusOK {
		t.Fatalf("expected 200, got %d: %s", rec.Code, rec.Body.String())
	}

	var resp map[string]string
	json.Unmarshal(rec.Body.Bytes(), &resp)
	if resp["path"] != fakeClaude {
		t.Errorf("expected path %q, got %q", fakeClaude, resp["path"])
	}
}

func TestClaudePath_MethodNotAllowed(t *testing.T) {
	s, _, _ := testServer(t)

	req := httptest.NewRequest(http.MethodDelete, "/api/claude-path", nil)
	rec := httptest.NewRecorder()
	s.ServeHTTP(rec, req)

	if rec.Code != http.StatusMethodNotAllowed {
		t.Fatalf("expected 405, got %d", rec.Code)
	}
}

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import InstallToolsModal from './InstallToolsModal';
import { api } from '../api';

vi.mock('../api', () => ({
  API_BASE: 'http://localhost:8080',
  isDesktopApp: false,
  api: {
    installTools: vi.fn(),
    checkInstallStatus: vi.fn(),
    setClaudePath: vi.fn(),
    listProjects: vi.fn().mockResolvedValue([]),
    getInReview: vi.fn().mockResolvedValue([]),
  },
}));

beforeEach(() => {
  vi.clearAllMocks();
});

// E-PENPAL-INSTALL-DISMISS: verifies install/update modal behavior, claude path prompt, and retry logic.
describe('InstallToolsModal', () => {
  it('renders with Install button for fresh install', () => {
    render(<InstallToolsModal open={true} isUpdate={false} onClose={() => {}} />);

    expect(screen.getByText('Install Command Line Tools')).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Install' })).toBeInTheDocument();
    expect(screen.getByText('Not Now')).toBeInTheDocument();
    expect(screen.getByText(/Install the/)).toBeInTheDocument();
  });

  it('renders with Update button when tools already exist', () => {
    render(<InstallToolsModal open={true} isUpdate={true} onClose={() => {}} />);

    expect(screen.getByText('Update Command Line Tools')).toBeInTheDocument();
    expect(screen.getByRole('button', { name: 'Update' })).toBeInTheDocument();
    expect(screen.getByText(/Update the/)).toBeInTheDocument();
  });

  it('does not render content when closed', () => {
    render(<InstallToolsModal open={false} isUpdate={false} onClose={() => {}} />);

    const overlay = document.querySelector('.modal-overlay');
    expect(overlay).not.toHaveClass('open');
  });

  it('calls onClose(false) when dismiss button is clicked without installing', () => {
    const onClose = vi.fn();
    render(<InstallToolsModal open={true} isUpdate={false} onClose={onClose} />);

    fireEvent.click(screen.getByText('Not Now'));
    expect(onClose).toHaveBeenCalledWith(false);
  });

  it('calls installTools API when install is clicked', async () => {
    vi.mocked(api.installTools).mockResolvedValue({
      cli: { installed: true, path: '/usr/local/bin/penpal' },
      plugin: { installed: true },
    });

    render(<InstallToolsModal open={true} isUpdate={false} onClose={() => {}} />);
    fireEvent.click(screen.getByText('Install'));

    await waitFor(() => {
      expect(api.installTools).toHaveBeenCalledTimes(1);
    });
  });

  it('shows success state and calls onClose(true) when done', async () => {
    vi.mocked(api.installTools).mockResolvedValue({
      cli: { installed: true, path: '/usr/local/bin/penpal' },
      plugin: { installed: true },
    });

    const onClose = vi.fn();
    render(<InstallToolsModal open={true} isUpdate={false} onClose={onClose} />);
    fireEvent.click(screen.getByText('Install'));

    await waitFor(() => {
      expect(screen.getByTestId('install-results')).toBeInTheDocument();
    });

    expect(screen.getByText(/installed at/)).toBeInTheDocument();
    expect(screen.getByText('Done')).toBeInTheDocument();
    // Install button should be gone after success
    expect(screen.queryByText('Install')).not.toBeInTheDocument();

    fireEvent.click(screen.getByText('Done'));
    expect(onClose).toHaveBeenCalledWith(true);
  });

  it('shows error state on failure', async () => {
    vi.mocked(api.installTools).mockResolvedValue({
