import { describe, expect, it } from 'vitest';
import {
  CURATED_ICONS,
  ICON_SEARCH_LIMIT,
  kebabToPascal,
  pascalToKebab,
  searchIconNames,
} from './iconNames';

describe('kebab ↔ Pascal icon names', () => {
  it('converts both ways for the shapes Lucide actually uses', () => {
    const pairs: [string, string][] = [
      ['play', 'Play'],
      ['flask-conical', 'FlaskConical'],
      ['layout-dashboard', 'LayoutDashboard'],
      // Single-letter and digit segments are where the inverse gets
      // interesting: a segment can be one letter ("arrow-down-a-z"), one digit
      // ("trash-2"), or open with a digit and carry on ("grid-2x2").
      ['a-arrow-up', 'AArrowUp'],
      ['arrow-down-a-z', 'ArrowDownAZ'],
      ['arrow-down-0-1', 'ArrowDown01'],
      ['map-pin-x-inside', 'MapPinXInside'],
      ['trash-2', 'Trash2'],
      ['grid-2x2', 'Grid2x2'],
      ['grid-2x2-plus', 'Grid2x2Plus'],
    ];

    for (const [kebab, pascal] of pairs) {
      expect(kebabToPascal(kebab)).toBe(pascal);
      expect(pascalToKebab(pascal)).toBe(kebab);
    }
  });

  it('round-trips whatever it produces, so a stored name always resolves back', () => {
    const names = [
      'Play',
      'FlaskConical',
      'Grid2x2',
      'Trash2',
      'SquareArrowOutUpRight',
      'AArrowUp',
      'ArrowDownAZ',
      // Ambiguous with ArrowDown01, so this one reads as "clock-1-0" rather
      // than lucide.dev's "clock-10" — still a name that resolves back.
      'Clock10',
    ];
    for (const pascal of names) {
      expect(kebabToPascal(pascalToKebab(pascal))).toBe(pascal);
    }
  });
});

describe('searchIconNames', () => {
  const names = ['play', 'play-circle', 'circle-play', 'rocket', 'wrench'];

  it('offers the curated set for an empty query when the map has every name', () => {
    expect(searchIconNames([...CURATED_ICONS, 'circle-play'], '   ')).toEqual(CURATED_ICONS);
  });

  it('drops curated names the loaded map lacks instead of surfacing them', () => {
    // A Lucide upgrade renaming a curated icon must degrade the shortlist,
    // not hand the grid a name that resolves to undefined.
    expect(searchIconNames(names, '   ')).toEqual(['play', 'rocket', 'wrench']);
  });

  it("offers a caller's own shortlist, filtered the same way", () => {
    expect(searchIconNames(names, '', ['wrench', 'gone', 'play'])).toEqual(['wrench', 'play']);
  });

  it('substring-matches anywhere in the name, and takes spaces for dashes', () => {
    expect(searchIconNames(names, 'play')).toEqual(['play', 'play-circle', 'circle-play']);
    expect(searchIconNames(names, 'Circle Play')).toEqual(['circle-play']);
  });

  it('caps results rather than painting every match', () => {
    const many = Array.from({ length: ICON_SEARCH_LIMIT + 20 }, (_, i) => `arrow-${i}`);
    expect(searchIconNames(many, 'arrow')).toHaveLength(ICON_SEARCH_LIMIT);
  });
});

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

describe('repo card bulk action hydration', () => {
  let invokeCommand: ReturnType<typeof vi.fn>;

  beforeEach(() => {
    vi.resetModules();
    invokeCommand = vi.fn();
    vi.doMock('../../transport', () => ({ invokeCommand, isTauri: true }));
  });

  afterEach(() => {
    vi.doUnmock('../../transport');
  });

  function action(name: string) {
    return {
      id: `action-${name}`,
      contextId: `context-${name}`,
      name,
      command: name,
      actionType: 'run',
      sortOrder: 0,
      createdAt: 0,
      updatedAt: 0,
    };
  }

  function execution(executionId: string, scopeId: string, phase: unknown = null) {
    return {
      executionId,
      branchId: scopeId,
      actionId: `action-${executionId}`,
      actionName: executionId,
      actionType: 'run',
      startedAt: 1,
      phase,
    };
  }

  it('folds same-tick callers into one list_all_repo_actions call, sliced per repo', async () => {
    invokeCommand.mockResolvedValue([
      {
        githubRepo: 'block/builderbot',
        subpath: 'apps/staged',
        actions: [action('dev')],
      },
      { githubRepo: 'block/goose', subpath: null, actions: [action('build')] },
    ]);

    const { bulkRepoActions } = await import('./repoActionsBulk');

    const [staged, goose, gooseEmptySubpath, contextless] = await Promise.all([
      bulkRepoActions('block/builderbot', 'apps/staged'),
      bulkRepoActions('block/goose'),
      // An empty subpath keys the same as no subpath at all.
      bulkRepoActions('block/goose', ''),
      bulkRepoActions('block/never-configured'),
    ]);

    expect(invokeCommand).toHaveBeenCalledTimes(1);
    expect(invokeCommand).toHaveBeenCalledWith('list_all_repo_actions');
    expect(staged.map((a) => a.name)).toEqual(['dev']);
    expect(goose.map((a) => a.name)).toEqual(['build']);
    expect(gooseEmptySubpath).toEqual(goose);
    // No context row yet reads as "no actions", not as an error.
    expect(contextless).toEqual([]);
  });

  it('starts a fresh wave once the previous one has resolved', async () => {
    invokeCommand.mockResolvedValue([]);

    const { bulkRepoActions } = await import('./repoActionsBulk');

    await bulkRepoActions('block/goose');
    await bulkRepoActions('block/goose');

    expect(invokeCommand).toHaveBeenCalledTimes(2);
  });

  it('rejects the callers of a failed wave without wedging the next one', async () => {
    invokeCommand
      .mockRejectedValueOnce(new Error('store not initialized'))
      .mockResolvedValueOnce([
        { githubRepo: 'block/goose', subpath: null, actions: [action('build')] },
      ]);

    const { bulkRepoActions } = await import('./repoActionsBulk');

    await expect(bulkRepoActions('block/goose')).rejects.toThrow('store not initialized');

    const retried = await bulkRepoActions('block/goose');
    expect(retried.map((a) => a.name)).toEqual(['build']);
  });

  it('keys running executions by scope id, phase included', async () => {
    const phase = { type: 'running', endpoint: 'http://localhost:3000' };
    invokeCommand.mockResolvedValue([
      execution('repo-run', 'repo:block/goose', phase),
      execution('repo-test', 'repo:block/goose'),
      execution('branch-run', 'branch-1'),
    ]);

    const { bulkRunningForScope } = await import('./repoActionsBulk');

    const [gooseRuns, branchRuns, idleScope] = await Promise.all([
      bulkRunningForScope('repo:block/goose'),
      bulkRunningForScope('branch-1'),
      bulkRunningForScope('repo:block/builderbot:apps/staged'),
    ]);

    expect(invokeCommand).toHaveBeenCalledTimes(1);
    expect(invokeCommand).toHaveBeenCalledWith('get_all_running_actions');
    expect(gooseRuns.map((s) => s.executionId)).toEqual(['repo-run', 'repo-test']);
    expect(gooseRuns[0].phase).toEqual(phase);
    expect(gooseRuns[1].phase).toBeNull();
    // Branch-scoped executions come back in the same call and stay separate.
    expect(branchRuns.map((s) => s.executionId)).toEqual(['branch-run']);
    expect(idleScope).toEqual([]);
  });
});

import { describe, expect, it } from 'vitest';
import { actionStatusLabels } from './actionStatusLabels';

const idle = { actionName: 'Dev', stopping: false, showStop: false, running: false } as const;

describe('actionStatusLabels', () => {
  it('names the action when it has never run', () => {
    expect(actionStatusLabels(idle)).toEqual({ title: 'Dev', ariaLabel: 'Dev' });
  });

  it('reports the outcome of a finished execution', () => {
    expect(actionStatusLabels({ ...idle, status: 'completed' })).toEqual({
      title: 'Dev completed',
      ariaLabel: 'Dev completed',
    });
    expect(actionStatusLabels({ ...idle, status: 'failed' })).toEqual({
      title: 'Dev failed',
      ariaLabel: 'Dev failed',
    });
  });

  it('names the action again once a stopped execution is the only history', () => {
    expect(actionStatusLabels({ ...idle, status: 'stopped' })).toEqual({
      title: 'Dev',
      ariaLabel: 'Dev',
    });
  });

  it('points a live execution at its output', () => {
    expect(actionStatusLabels({ ...idle, running: true, status: 'running' })).toEqual({
      title: 'View output for Dev',
      ariaLabel: 'View output for Dev',
    });
  });

  it('offers to stop while the alt affordance is showing', () => {
    expect(
      actionStatusLabels({ ...idle, showStop: true, running: true, status: 'running' })
    ).toEqual({ title: 'Stop Dev', ariaLabel: 'Stop Dev' });
  });

  it('drops the tooltip ellipsis from the accessible name while stopping', () => {
    expect(
      actionStatusLabels({ ...idle, stopping: true, running: true, status: 'running' })
    ).toEqual({ title: 'Stopping…', ariaLabel: 'Stopping' });
  });

  it('prefers the more specific rung when several apply', () => {
    // Stopping wins over the stop affordance, which wins over "view output",
    // which wins over a status that has already been superseded.
    expect(
      actionStatusLabels({
        ...idle,
        stopping: true,
        showStop: true,
        running: true,
        status: 'completed',
      }).title
    ).toBe('Stopping…');
    expect(
      actionStatusLabels({ ...idle, showStop: true, running: true, status: 'completed' }).title
    ).toBe('Stop Dev');
    expect(actionStatusLabels({ ...idle, running: true, status: 'completed' }).title).toBe(
      'View output for Dev'
    );
  });
});

import { describe, expect, it, vi } from 'vitest';
