    vi.doMock('svelte-sonner', () => ({ toast: { error: vi.fn() } }));
  });

  afterEach(() => {
    vi.unstubAllGlobals();
    vi.doUnmock('./actions');
    vi.doUnmock('../../services/branchEventService');
    vi.doUnmock('svelte-sonner');
  });

  function snapshot(executionId: string, actionType: string, phase: unknown) {
    return {
      executionId,
      branchId: 'repo:block/goose',
      actionId: `action-${executionId}`,
      actionName: executionId,
      actionType,
      startedAt: 7,
      phase,
    };
  }

  async function newRunner(opts: Record<string, unknown>) {
    const { ActionRunner } = await import('./actionRunner.svelte');
    return new ActionRunner({
      getScopeId: () => 'repo:block/goose',
      loadActions: async () => [],
      run: async () => 'execution-1',
      ...opts,
    } as never);
  }

  it('hydrates from an injected bulk loader without any per-execution phase calls', async () => {
    const buildingPhase = { type: 'building' };
    const loadRunning = vi
      .fn()
      .mockResolvedValue([
        snapshot('run-with-phase', 'run', buildingPhase),
        snapshot('run-without-phase', 'run', null),
        snapshot('test-without-phase', 'test', null),
      ]);

    const runner = await newRunner({ loadRunning });
    await runner.loadRunningActions();

    expect(loadRunning).toHaveBeenCalledTimes(1);
    expect(getRunningBranchActions).not.toHaveBeenCalled();
    expect(getRunPhase).not.toHaveBeenCalled();

    expect(runner.runningActions.map((a) => a.executionId)).toEqual([
      'run-with-phase',
      'run-without-phase',
      'test-without-phase',
    ]);
    expect(runner.runningActions.every((a) => a.status === 'running')).toBe(true);
    expect(runner.runPhases.get('run-with-phase')).toEqual(buildingPhase);
    // A phaseless run action still shows as running; other types get no phase.
    expect(runner.runPhases.get('run-without-phase')).toEqual({
      type: 'running',
      endpoint: null,
    });
    expect(runner.runPhases.has('test-without-phase')).toBe(false);

    // Re-hydrating leaves the tracked set alone rather than duplicating it.
    await runner.loadRunningActions();
    expect(runner.runningActions).toHaveLength(3);
  });

  it('falls back to per-scope and per-execution calls when no bulk loader is given', async () => {
    getRunningBranchActions.mockResolvedValue([snapshot('branch-run', 'run', undefined)]);
    getRunPhase.mockResolvedValue({ type: 'running', endpoint: 'http://localhost:5173' });

    const runner = await newRunner({});
    await runner.loadRunningActions();

    expect(getRunningBranchActions).toHaveBeenCalledWith('repo:block/goose');
    expect(getRunPhase).toHaveBeenCalledWith('branch-run');
    expect(runner.runPhases.get('branch-run')).toEqual({
      type: 'running',
      endpoint: 'http://localhost:5173',
    });
  });

  it('distinguishes an empty action list from a failed load', async () => {
    const consoleError = vi.spyOn(console, 'error').mockImplementation(() => {});
    try {
      const empty = await newRunner({ loadActions: async () => [] });
      expect(await empty.loadActions()).toBe(true);

      const failing = await newRunner({
        loadActions: async () => {
          throw new Error('IPC unavailable');
        },
      });
      // A failure still empties the list, so the boolean is the only way a
      // caller can tell it apart from a context with no actions.
      expect(await failing.loadActions()).toBe(false);
      expect(failing.actions).toEqual([]);
    } finally {
      consoleError.mockRestore();
    }
  });

  it('hands each pinned button its own execution, and none to an idle one', async () => {
    const runner = await newRunner({});
    runner.runningActions.push(
      {
        executionId: 'execution-dev',
        actionId: 'action-dev',
        actionName: 'Dev',
        actionType: 'run',
        status: 'running',
      },
      {
        executionId: 'execution-test',
        actionId: 'action-test',
        actionName: 'Test',
        actionType: 'test',
        status: 'completed',
      }
    );

    // Several pinned actions can be in flight at once, so a button looks up
    // its own action rather than sharing one "the primary execution" slot.
    expect(runner.executionFor('action-dev')?.executionId).toBe('execution-dev');
    expect(runner.executionFor('action-test')?.status).toBe('completed');
    expect(runner.executionFor('action-build')).toBeNull();
  });

  it('focuses a running execution instead of starting a second one', async () => {
    const run = vi.fn().mockResolvedValue('execution-2');
    const runner = await newRunner({ run });
    runner.runningActions.push({
      executionId: 'execution-1',
      actionId: 'action-1',
      actionName: 'Dev',
      actionType: 'run',
      status: 'running',
    });

    await runner.runAction({ id: 'action-1', name: 'Dev' } as never);

    expect(run).not.toHaveBeenCalled();
    expect(runner.outputModal?.executionId).toBe('execution-1');
  });

  it('opens the modal only when a re-run starts the execution', async () => {
    const action = { id: 'action-1', name: 'Dev' };
    const run = vi.fn().mockResolvedValue('execution-2');

    // The run button starts the action without pulling up the modal...
    const fromButton = await newRunner({ run });
    await fromButton.runAction(action as never);
    expect(run).toHaveBeenCalledWith('action-1');
    expect(fromButton.outputModal).toBeNull();

    // ...while Run Again repoints the open modal at the new execution.
    const fromModal = await newRunner({ loadActions: async () => [action], run });
    await fromModal.loadActions();
    fromModal.outputModal = {
      executionId: 'execution-1',
      actionId: 'action-1',
      actionName: 'Dev',
      isStopping: false,
    };
    await fromModal.runAgain();
    expect(fromModal.outputModal).toEqual({
      executionId: 'execution-2',
      actionId: 'action-1',
      actionName: 'Dev',
      isStopping: false,
    });
  });
});

import { describe, it, expect } from 'vitest';
import { processChunksToLines, createIncrementalProcessor } from './processOutput';
import type { OutputChunk } from './actions';

/** Helper to build an OutputChunk. */
function chunk(text: string, stream: 'stdout' | 'stderr' = 'stdout'): OutputChunk {
  return { chunk: text, stream, timestamp: 0 };
}

/** Helper to extract just the text from result lines. */
function texts(chunks: OutputChunk[]): string[] {
  return processChunksToLines(chunks).map((l) => l.text);
}

describe('processChunksToLines', () => {
  // ---------------------------------------------------------------------------
  // Basic newline handling
  // ---------------------------------------------------------------------------

  it('splits on \\n', () => {
    expect(texts([chunk('hello\nworld\n')])).toEqual(['hello', 'world']);
  });

  it('keeps a trailing line that has no terminating newline', () => {
    expect(texts([chunk('hello\nworld')])).toEqual(['hello', 'world']);
  });

  it('handles empty input', () => {
    expect(texts([])).toEqual([]);
  });

  it('handles a single chunk with no newlines', () => {
    expect(texts([chunk('hello')])).toEqual(['hello']);
  });

  // ---------------------------------------------------------------------------
  // \\r\\n (CRLF) handling
  // ---------------------------------------------------------------------------

  it('treats \\r\\n as a single newline', () => {
    expect(texts([chunk('hello\r\nworld\r\n')])).toEqual(['hello', 'world']);
  });

  it('handles \\r\\n split across two chunks', () => {
    expect(texts([chunk('hello\r'), chunk('\nworld')])).toEqual(['hello', 'world']);
  });

  // ---------------------------------------------------------------------------
  // Bare \\r (carriage return) — progress bar behavior
  // ---------------------------------------------------------------------------

  it('bare \\r overwrites the current line (single chunk)', () => {
    expect(texts([chunk('progress 50%\rprogress 100%\n')])).toEqual(['progress 100%']);
  });

  it('bare \\r overwrites across multiple updates in one chunk', () => {
    expect(texts([chunk('10%\r20%\r30%\r40%\n')])).toEqual(['40%']);
  });

  it('bare \\r overwrites across separate chunks', () => {
    expect(texts([chunk('downloading 50%\r'), chunk('downloading 100%\n')])).toEqual([
      'downloading 100%',
    ]);
  });

  it('bare \\r at end of chunk followed by non-\\n text in next chunk overwrites', () => {
    expect(texts([chunk('old text\r'), chunk('new text')])).toEqual(['new text']);
  });

  it('multiple progress updates across separate chunks collapse correctly', () => {
    expect(texts([chunk('10%\r'), chunk('20%\r'), chunk('30%\r'), chunk('done\n')])).toEqual([
      'done',
    ]);
  });

  it('progress bar followed by normal output', () => {
    expect(texts([chunk('building...\rprogress 50%\rprogress 100%\nSuccess!\n')])).toEqual([
      'progress 100%',
      'Success!',
    ]);
  });

  // ---------------------------------------------------------------------------
  // Mixed scenarios
  // ---------------------------------------------------------------------------

  it('handles normal lines before and after progress bars', () => {
    expect(
      texts([chunk('Starting build\n'), chunk('0%\r50%\r100%\n'), chunk('Build complete\n')])
    ).toEqual(['Starting build', '100%', 'Build complete']);
  });

  it('handles interleaved stdout and stderr', () => {
    const result = processChunksToLines([
      chunk('out line\n', 'stdout'),
      chunk('err line\n', 'stderr'),
    ]);
    expect(result).toEqual([
      { text: 'out line', stream: 'stdout' },
      { text: 'err line', stream: 'stderr' },
    ]);
  });

  it('bare \\r at the very end of all chunks produces no trailing line', () => {
    // A progress bar that never finishes with \n — should show nothing
    // because the \r resets the line and there's no further content.
    expect(texts([chunk('in progress\r')])).toEqual([]);
  });

  it('empty lines are preserved', () => {
    expect(texts([chunk('a\n\nb\n')])).toEqual(['a', '', 'b']);
  });

  it('handles chunk boundaries mid-text', () => {
    expect(texts([chunk('hel'), chunk('lo\nwor'), chunk('ld\n')])).toEqual(['hello', 'world']);
  });
});

// ---------------------------------------------------------------------------
// createIncrementalProcessor
// ---------------------------------------------------------------------------

describe('createIncrementalProcessor', () => {
  /** Helper: feed chunks one-at-a-time and return the final snapshot. */
  function feedOneByOne(chunks: OutputChunk[]): string[] {
    const proc = createIncrementalProcessor();
    let result: ReturnType<typeof proc.process> = [];
    for (const c of chunks) {
      result = proc.process([c]);
    }
    return result.map((l) => l.text);
  }

  /** Helper: feed all chunks at once. */
  function feedAll(chunks: OutputChunk[]): string[] {
    const proc = createIncrementalProcessor();
    return proc.process(chunks).map((l) => l.text);
  }

  // ---------------------------------------------------------------------------
  // Parity with processChunksToLines
  // ---------------------------------------------------------------------------

  it('matches batch output for simple newlines', () => {
    const chunks = [chunk('hello\nworld\n')];
    expect(feedAll(chunks)).toEqual(texts(chunks));
  });

  it('matches batch output for \\r\\n', () => {
    const chunks = [chunk('hello\r\nworld\r\n')];
    expect(feedAll(chunks)).toEqual(texts(chunks));
  });

  it('matches batch output for bare \\r overwrites', () => {
    const chunks = [chunk('10%\r20%\r30%\r40%\n')];
    expect(feedAll(chunks)).toEqual(texts(chunks));
  });

  it('matches batch output for interleaved stdout/stderr', () => {
    const chunks = [chunk('out\n', 'stdout'), chunk('err\n', 'stderr')];
    const proc = createIncrementalProcessor();
    let result = proc.process([chunks[0]]);
    result = proc.process([chunks[1]]);
    expect(result.map((l) => l.stream)).toEqual(['stdout', 'stderr']);
  });

  // ---------------------------------------------------------------------------
  // Incremental accumulation
  // ---------------------------------------------------------------------------

  it('accumulates lines across multiple process() calls', () => {
    const proc = createIncrementalProcessor();
    proc.process([chunk('line1\n')]);
    const result = proc.process([chunk('line2\n')]);
    expect(result.map((l) => l.text)).toEqual(['line1', 'line2']);
  });

  it('shows in-progress line until finalized', () => {
    const proc = createIncrementalProcessor();
    let result = proc.process([chunk('partial')]);
    expect(result.map((l) => l.text)).toEqual(['partial']);
    result = proc.process([chunk(' more\n')]);
    expect(result.map((l) => l.text)).toEqual(['partial more']);
  });

  // ---------------------------------------------------------------------------
  // \\r\\n split across process() calls — the key correctness case
  // ---------------------------------------------------------------------------

  it('preserves line text when \\r\\n is split across calls', () => {
    const proc = createIncrementalProcessor();
    // First call ends with \r — we don't yet know if it's bare \r or \r\n
    let result = proc.process([chunk('hello\r')]);
    // The text should still be visible (not discarded)
    expect(result.map((l) => l.text)).toEqual(['hello']);
    // Second call starts with \n — confirms it was \r\n, line should be finalized
    result = proc.process([chunk('\nworld\n')]);
    expect(result.map((l) => l.text)).toEqual(['hello', 'world']);
  });

  it('bare \\r across calls correctly overwrites when followed by non-\\n', () => {
    const proc = createIncrementalProcessor();
    proc.process([chunk('old text\r')]);
    const result = proc.process([chunk('new text\n')]);
    expect(result.map((l) => l.text)).toEqual(['new text']);
  });

  it('multiple trailing \\r across calls resolve correctly', () => {
    const proc = createIncrementalProcessor();
    proc.process([chunk('10%\r')]);
    proc.process([chunk('20%\r')]);
    proc.process([chunk('30%\r')]);
    const result = proc.process([chunk('done\n')]);
    expect(result.map((l) => l.text)).toEqual(['done']);
  });

  // ---------------------------------------------------------------------------
  // Batched chunks (multiple chunks in one process() call)
  // ---------------------------------------------------------------------------

  it('handles multiple chunks in a single process() call', () => {
    const proc = createIncrementalProcessor();
    const result = proc.process([chunk('hello\n'), chunk('world\n')]);
    expect(result.map((l) => l.text)).toEqual(['hello', 'world']);
  });
});

import { describe, expect, it } from 'vitest';
import type { ProjectAction } from '../../api/commands';
import {
  createActionGroups,
  getPinnedActions,
  getSecondaryRunningActions,
  groupActionsByType,
  shouldPinNewAction,
} from './actionGroups';

function action(
  name: string,
  overrides: Partial<ProjectAction> & Pick<ProjectAction, 'actionType' | 'sortOrder'>
): ProjectAction {
  return {
    id: `action-${name}`,
    contextId: 'context-1',
    name,
    command: name,
    pinned: false,
    icon: null,
    createdAt: 0,
    updatedAt: 0,
    ...overrides,
  };
}

describe('getPinnedActions', () => {
  it('returns every pinned action in sort order, whatever its type', () => {
    const actions = [
      action('Test', { actionType: 'test', sortOrder: 3, pinned: true, icon: 'flask-conical' }),
      action('Build', { actionType: 'build', sortOrder: 2 }),
      action('Dev', { actionType: 'run', sortOrder: 1, pinned: true }),
      action('Storybook', { actionType: 'run', sortOrder: 0, pinned: true, icon: 'palette' }),
    ];

    expect(getPinnedActions(actions).map((a) => a.name)).toEqual(['Storybook', 'Dev', 'Test']);
  });

  it('is empty when nothing is pinned — a header with no action buttons', () => {
    const actions = [
      action('Dev', { actionType: 'run', sortOrder: 0 }),
      action('Test', { actionType: 'test', sortOrder: 1 }),
    ];

    expect(getPinnedActions(actions)).toEqual([]);
  });
});

describe('shouldPinNewAction', () => {
  it('pins the first action a hand-built context gets, so its header is not empty', () => {
    expect(shouldPinNewAction([])).toBe(true);
    expect(
      shouldPinNewAction([
        action('Test', { actionType: 'test', sortOrder: 0 }),
        action('Build', { actionType: 'build', sortOrder: 1 }),
      ])
    ).toBe(true);
  });

  it('leaves later actions unpinned once the header has a button', () => {
    expect(
      shouldPinNewAction([
        action('Dev', { actionType: 'run', sortOrder: 0, pinned: true }),
        action('Test', { actionType: 'test', sortOrder: 1 }),
      ])
    ).toBe(false);
  });

  it('does not treat an unpinned run action as filling the header', () => {
    expect(shouldPinNewAction([action('Dev', { actionType: 'run', sortOrder: 0 })])).toBe(true);
  });
});

describe('getSecondaryRunningActions', () => {
  const running = [
    { actionId: 'action-Dev' },
    { actionId: 'action-Test' },
    { actionId: 'action-Build' },
  ];

  it('drops every pinned action, not just one', () => {
    const pinned = new Set(['action-Dev', 'action-Build']);
    expect(getSecondaryRunningActions(running, pinned)).toEqual([{ actionId: 'action-Test' }]);
  });

  it('keeps everything when nothing is pinned', () => {
    expect(getSecondaryRunningActions(running, new Set())).toEqual(running);
  });
});

describe('groupActionsByType', () => {
  it('creates one empty bucket for every supported type in display order', () => {
    expect(Object.keys(createActionGroups())).toEqual([
      'run',
      'prerun',
      'build',
      'test',
      'format',
      'check',
      'cleanUp',
    ]);
  });

  it('buckets actions by type and leaves unknown types out', () => {
    const groups = groupActionsByType([
      action('Dev', { actionType: 'run', sortOrder: 0 }),
      action('Test', { actionType: 'test', sortOrder: 1 }),
      action('Mystery', { actionType: 'nonsense' as ProjectAction['actionType'], sortOrder: 2 }),
    ]);

    expect(groups.run.map((a) => a.name)).toEqual(['Dev']);
    expect(groups.test.map((a) => a.name)).toEqual(['Test']);
    expect(
      Object.values(groups)
        .flat()
        .map((a) => a.name)
    ).not.toContain('Mystery');
  });
});

